import { parseAddr } from './addr.js'
import { parseFormula, rangeCells } from './formula.js'

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ t: 'err', v: e })
const num = (v) => ({ t: 'num', v })

export function formatValue(v) {
  switch (v.t) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function literal(s) {
  if (s === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERRS.includes(s)) return err(s)
  return { t: 'text', v: s }
}

export function evaluateAll(cells) {
  const memo = new Map()
  const active = new Set()

  function cellValue(name) {
    const c = cells.get(name)
    if (!c) return num(0)
    if (memo.has(name)) return memo.get(name)
    if (active.has(name)) return err('#CYCLE!')
    active.add(name)
    let v
    if (c.content.startsWith('=')) {
      const ast = parseFormula(c.content.slice(1))
      v = !ast || ast.bad ? err('#ERR!') : ev(ast)
    } else v = literal(c.content)
    active.delete(name)
    memo.set(name, v)
    return v
  }

  // numeric coercion: returns number or error value
  function toNum(v) {
    if (v.t === 'num') return v.v
    if (v.t === 'bool') return v.v ? 1 : 0
    return err('#VALUE!')
  }
  const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

  function ev(n) {
    switch (n.k) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'bool', v: n.v }
      case 'paren': return ev(n.e)
      case 'ref': {
        const a = parseAddr(n.w)
        return a ? cellValue(a.name) : err('#REF!')
      }
      case 'range': return err('#ERR!')
      case 'un': {
        const v = ev(n.e)
        if (v.t === 'err') return v
        const x = toNum(v)
        if (typeof x !== 'number') return x
        return num(n.op === '-' ? -x : x)
      }
      case 'bin': {
        const l = ev(n.l), r = ev(n.r)
        if (l.t === 'err') return l
        if (r.t === 'err') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const c = compare(l, r)
          const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
          return { t: 'bool', v: res }
        }
        const a = toNum(l)
        if (typeof a !== 'number') return a
        const b = toNum(r)
        if (typeof b !== 'number') return b
        switch (n.op) {
          case '+': return fin(a + b)
          case '-': return fin(a - b)
          case '*': return fin(a * b)
          case '/': return b === 0 ? err('#DIV/0!') : fin(a / b)
          case '^': return fin(Math.pow(a, b))
        }
      }
      case 'call': return call(n)
    }
  }

  function compare(l, r) {
    const rank = { num: 0, text: 1, bool: 2 }
    if (l.t !== r.t) return rank[l.t] - rank[r.t]
    if (l.t === 'text') {
      const a = [...l.v], b = [...r.v]
      for (let i = 0; i < Math.min(a.length, b.length); i++) {
        const d = a[i].codePointAt(0) - b[i].codePointAt(0)
        if (d) return d
      }
      return a.length - b.length
    }
    const a = Number(l.v), b = Number(r.v)
    return a < b ? -1 : a > b ? 1 : 0
  }

  function call(n) {
    const name = n.name, args = n.args
    const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
    if (!known.includes(name)) return err('#NAME?')
    const arity = name === 'ABS' ? args.length === 1 : name === 'IF' ? args.length === 3 : args.length >= 1
    if (!arity) return err('#ERR!')
    if (name === 'IF') {
      if (args.some((a) => a.k === 'range')) return err('#ERR!')
      const c = ev(args[0])
      if (c.t === 'err') return c
      let truth
      if (c.t === 'bool') truth = c.v
      else if (c.t === 'num') truth = c.v !== 0
      else return err('#VALUE!')
      return ev(truth ? args[1] : args[2])
    }
    const vals = []
    for (const a of args) {
      if (a.k === 'range') {
        const cs = rangeCells(a)
        if (!cs) return err('#REF!')
        for (const c of cs) vals.push(cellValue(c))
      } else vals.push(ev(a))
    }
    const e = vals.find((v) => v.t === 'err')
    if (e) return e
    if (name === 'ABS' && args[0].k === 'range') return err('#ERR!')
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'num').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (typeof x !== 'number') return x
      nums.push(x)
    }
    switch (name) {
      case 'ABS': return fin(Math.abs(nums[0]))
      case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
      case 'MIN': return fin(Math.min(...nums))
      case 'MAX': return fin(Math.max(...nums))
      case 'AVG': return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
  }

  const out = new Map()
  for (const name of cells.keys()) out.set(name, cellValue(name))
  return out
}
