import { parseAddr } from './addr.js'

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(line)
    const word = m[1]
    const a = parseAddr(word)
    if (!a) throw new Error(`error: line ${i + 1}: invalid cell address ${word}`)
    if (cells.has(a.name)) throw new Error(`error: line ${i + 1}: cell ${a.name} is declared twice`)
    cells.set(a.name, { name: a.name, col: a.col, row: a.row, content: m[2] })
  })
  return cells
}
