import { parseAddr, addrKey } from './addr.js'

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[<>=+\-*\/^(),:])/.exec(s.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue }
    return null
  }
  return toks
}

// Returns AST, or null when the grammar rejects it. ast.bad marks a misplaced range.
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw null }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { k: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) fail()
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return { k: 'paren', e }
    }
    if (t.t === 'word') {
      p++
      const up = t.v.toUpperCase()
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { k: 'call', name: up, args }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.t !== 'word') fail()
        p++
        return { k: 'range', a: t.v, b: t2.v }
      }
      if (up === 'TRUE') return { k: 'bool', v: true }
      if (up === 'FALSE') return { k: 'bool', v: false }
      return { k: 'ref', w: t.v }
    }
    fail()
  }
  try {
    const ast = cmp()
    if (p !== toks.length) return null
    ast.bad = hasBadRange(ast, false)
    return ast
  } catch (e) {
    if (e === null) return null
    throw e
  }
}

function hasBadRange(n, argPos) {
  switch (n.k) {
    case 'range': return !argPos
    case 'bin': return hasBadRange(n.l, false) || hasBadRange(n.r, false)
    case 'un': case 'paren': return hasBadRange(n.e, false)
    case 'call': return n.args.some((a) => hasBadRange(a, true))
    default: return false
  }
}

export function rangeCells(n) {
  const a = parseAddr(n.a), b = parseAddr(n.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) out.push(addrKey(c, r))
  return out
}

export function depsOf(ast) {
  const set = new Map()
  const add = (a) => set.set(a.name, a)
  ;(function walk(n) {
    switch (n.k) {
      case 'ref': { const a = parseAddr(n.w); if (a) add(a); break }
      case 'range': {
        const a = parseAddr(n.a), b = parseAddr(n.b)
        if (a && b) {
          for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
            for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) add(parseAddr(addrKey(c, r)))
        } else { if (a) add(a); if (b) add(b) }
        break
      }
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'paren': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  })(ast)
  return [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row).map((a) => a.name)
}
